SELECT 
    ?university ?universityType
WHERE {
    ?university ex:hadFirstChairmanOfBoard ex:Reverend_Lyttleton_Morgan .
    ?university ex:type ?universityType .
    FILTER(?universityType = "public" || ?universityType = "private")

    VALUES ?idahoUniversity { ex:University_of_Idaho }
    ?idahoUniversity ex:type ?idahoType .
}

