SELECT ?film ?screenplayBasedOn WHERE {
  ?film rdfs:label "The Night Hunter"@en.
  ?film wdt:P58 ?screenwriter.
  OPTIONAL { ?film wdt:P144 ?workAdaptedFrom. }
  ?workAdaptedFrom wdt:P31 wd:Q571. # Check if adaptation is from a novel
}
SELECT ?writer WHERE {
  ?writer rdfs:label ?writerName.
  FILTER(?writerName != "Nelly Sachs")
  ?writer wdt:P166 wd:Q37922. # Nobel Prize in Literature
}
SELECT ?nobelSachs WHERE {
  ?nobelSachs rdfs:label "Nelly Sachs"@en.
  ?nobelSachs wdt:P166 wd:Q37922.
}

